const baseRenderAssets=renderAssets;renderAssets=function(){baseRenderAssets();document.querySelectorAll('.asset-item').forEach((d,i)=>{let a=assets[i];d.draggable=true;d.title='Toca para aplicar · doble toque para previsualizar · arrastra a la pista';d.ondblclick=e=>{e.preventDefault();openPreview(a)};d.ondragstart=e=>e.dataTransfer.setData('text/faas-preview',JSON.stringify({assetId:a.id}))})};
canvas.addEventListener('dragover',e=>e.preventDefault());canvas.addEventListener('drop',e=>{e.preventDefault();let raw=e.dataTransfer.getData('text/faas-preview');if(!raw)return;let data;try{data=JSON.parse(raw)}catch{return}let q=pointerPos(e),p=unproject(q.x,q.y);if(data.type){addObject(data.type,p.x,p.y);status(data.type+' colocado desde la vista previa')}else if(data.assetId){let a=assets.find(x=>x.id===data.assetId);if(a){let cat=(a.category||'').toLowerCase();if(cat.includes('ambiente')||cat.includes('escenario')){history();let d=a.dimensions||{width:6,depth:3,height:1.2};sceneObjects.push({id:uid(),assetId:a.id,name:a.name,category:a.category,description:a.description,material:a.material,color:a.color,src:a.src,x:p.x,y:p.y,scale:1,rotation:0,dimensions:d});updateUI();draw();status('Elemento 3D colocado desde la vista previa')}else{addObject('Vertical',p.x,p.y);selected.decals=selected.decals||[];let id=uid();selected.decals.push({id,kind:'logo',name:a.name,src:a.src,target:'side',scale:1,offsetX:0,offsetY:0,rotation:0,assetId:a.id});logoImages[id]=null;updateUI();draw();status('Referencia colocada sobre un obstáculo')}}}});

// Fase 3: mediciones del elemento seleccionado y referencia directa de trancos.
function pathLength(points){let total=0;for(let i=1;i<points.length;i++)total+=Math.hypot(points[i].x-points[i-1].x,points[i].y-points[i-1].y);return total}
function routeMeasurement(n){if(!n)return null;if(n.kind==='circle'){let circumference=2*Math.PI*n.r;return{length:circumference,detail:`Radio: ${n.r.toFixed(1)} m · Diámetro: ${(n.r*2).toFixed(1)} m`}}let points=n.kind==='line'?[n.a,n.b]:catmull(nodePoints(n),24);return{length:pathLength(points),detail:n.kind==='line'?'Tramo recto':n.kind==='connection'?'Tramo conectado':'Curva suavizada'}}
function updateLineMetrics(){let box=$('#lineMetrics'),n=lineNode();if(!box)return;if(!n){box.textContent='Medición: —';return}let data=routeMeasurement(n),stride=Math.max(2,+$('#strideLength').value||3.5),strides=data.length/stride;box.textContent=`${data.detail} · Longitud: ${data.length.toFixed(1)} m · ${strides.toFixed(1)} trancos`}
const phase3RefreshLineInspector=refreshLineInspector;refreshLineInspector=function(){phase3RefreshLineInspector();updateLineMetrics()};
const phase3UpdateMetrics=updateMetrics;updateMetrics=function(){phase3UpdateMetrics();updateLineMetrics()};
const phase3DrawRouteHandles=drawRouteHandles;drawRouteHandles=function(){phase3DrawRouteHandles();if(!routeSelection||!['line','curve','connection','circle'].includes(routeSelection.kind))return;let data=routeMeasurement(routeSelection);if(!data)return;let pts=routeSelection.kind==='circle'?[{x:routeSelection.cx,y:routeSelection.cy}]:nodePoints(routeSelection),mid=pts[Math.floor(pts.length/2)],q=project(mid.x,mid.y,.32);ctx.save();ctx.font='bold 12px system-ui';ctx.textAlign='center';ctx.textBaseline='middle';let label=`${data.length.toFixed(1)} m`;let width=ctx.measureText(label).width+18;ctx.fillStyle='#07111fe8';ctx.strokeStyle='#57e389';ctx.lineWidth=1;ctx.beginPath();ctx.roundRect(q.x-width/2,q.y-32,width,24,7);ctx.fill();ctx.stroke();ctx.fillStyle='#dfffe9';ctx.fillText(label,q.x,q.y-20);ctx.restore()};

// Paquete integrado Fase 3: señalización, controles de recorrido, validación por tramo y cámaras.
const phase3DrawJump=drawJump;drawJump=function(o){phase3DrawJump(o);let p=project(o.x,o.y,o.height+.42),a=o.rot*Math.PI/180;ctx.save();ctx.translate(p.x,p.y);ctx.rotate(a);ctx.fillStyle='#39bdf8';ctx.strokeStyle='#07111f';ctx.lineWidth=1.5;ctx.beginPath();ctx.moveTo(15,0);ctx.lineTo(-8,-7);ctx.lineTo(-4,0);ctx.lineTo(-8,7);ctx.closePath();ctx.fill();ctx.stroke();ctx.restore()};
function courseOrderedObjects(){return courseBaseNodes().filter(n=>n.kind==='obstacle').map(n=>objects.find(o=>o.id===n.objectId)).filter(Boolean)}
function courseSegmentData(){let ordered=courseOrderedObjects(),start=route.find(n=>n.kind==='point'&&n.marker==='start'),finish=route.find(n=>n.kind==='point'&&n.marker==='finish'),nodes=[];if(start)nodes.push({label:'Salida',x:start.x,y:start.y});ordered.forEach(o=>nodes.push({label:(o.num||'?')+' · '+o.type,x:o.x,y:o.y}));if(finish)nodes.push({label:'Llegada',x:finish.x,y:finish.y});let stride=Math.max(2,+$('#strideLength').value||3.5),out=[];for(let i=1;i<nodes.length;i++){let a=nodes[i-1],b=nodes[i],meters=Math.hypot(b.x-a.x,b.y-a.y);out.push({from:a.label,to:b.label,meters,strides:meters/stride})}return out}
function renderCourseBreakdown(){let box=$('#courseBreakdown');if(!box)return;let data=courseSegmentData();box.innerHTML='';data.forEach(s=>{let item=document.createElement('div');item.className='item';item.innerHTML=`<span><b>${s.from} → ${s.to}</b><br><small>${s.meters.toFixed(1)} m · ${s.strides.toFixed(1)} trancos</small></span>`;box.appendChild(item)})}
const phase3UpdateMetricsWithSegments=updateMetrics;updateMetrics=function(){phase3UpdateMetricsWithSegments();renderCourseBreakdown()};
const phase3ValidateCourse=validateCourse;validateCourse=function(){phase3ValidateCourse();let segments=courseSegmentData(),warnings=segments.filter(s=>s.meters<4||s.meters>70);if(segments.length&&warnings.length){let base=$('#validation').textContent;$('#validation').textContent=base+' · ⚠ '+warnings.length+' tramo(s) fuera del rango de revisión';$('#validation').style.color='#ffd166'}renderCourseBreakdown()};
const phase3UpdateUIFinal=updateUI;updateUI=function(){phase3UpdateUIFinal();updateMetrics()};
function setCameraPreset(name){let presets={cenital:{view:'top',yaw:-32,pitch:75,zoom:10},drone:{view:'3d',yaw:-38,pitch:58,zoom:11},jinete:{view:'3d',yaw:-12,pitch:28,zoom:14},cinematica:{view:'3d',yaw:-58,pitch:42,zoom:12}}[name];if(!presets)return;view=presets.view;yaw=presets.yaw*Math.PI/180;pitch=presets.pitch*Math.PI/180;zoom=presets.zoom;$('#yaw').value=presets.yaw;$('#pitch').value=presets.pitch;$('#zoom').value=zoom;$('#camPill').textContent='Cámara: '+(name==='cenital'?'cenital':name);draw();status('Cámara '+name+' activada')}
$('#cameraTop').onclick=()=>setCameraPreset('cenital');$('#cameraDrone').onclick=()=>setCameraPreset('drone');$('#cameraRider').onclick=()=>setCameraPreset('jinete');$('#cameraCinema').onclick=()=>setCameraPreset('cinematica');

// Presentación visual final: ambiente de día, atardecer o noche sin alterar la geometría del diseño.
let environmentMode='day';
const phase3PresentationDraw=draw;draw=function(){phase3PresentationDraw();let r=canvas.getBoundingClientRect();if(environmentMode==='day')return;ctx.save();if(environmentMode==='sunset'){let g=ctx.createLinearGradient(0,0,0,r.height);g.addColorStop(0,'#e86f3faa');g.addColorStop(.5,'#e8a74e33');g.addColorStop(1,'#3b2b3477');ctx.fillStyle=g;ctx.fillRect(0,0,r.width,r.height)}else{ctx.fillStyle='#07132a88';ctx.fillRect(0,0,r.width,r.height);ctx.fillStyle='#dbeeff';for(let i=0;i<36;i++){let x=(i*83)%r.width,y=(i*47)%Math.max(120,r.height*.42);ctx.fillRect(x,y,1.5,1.5)}}ctx.restore()};
$('#environmentMode').onchange=e=>{environmentMode=e.target.value;draw();status('Ambiente '+(environmentMode==='day'?'de día':environmentMode==='sunset'?'atardecer':'noche')+' activado')};

const obstacleStyles={classic:{color:'#f7f3e8',material:'Madera',parts:['bar','bar']},sponsor:{color:'#1976d2',material:'Metal lacado',parts:['bar','panel']},natural:{color:'#8b5a2b',material:'Madera natural',parts:['plank','filler']},water:{color:'#42b9e8',material:'Agua y plástico',parts:['panel','rail']}};
function applyObstacleStyle(name){if(!selected){status('Selecciona un obstáculo primero');return}let style=obstacleStyles[name]||obstacleStyles.classic;history();selected.parts=[];style.parts.forEach((kind,i)=>selected.parts.push({id:uid(),kind,z:kind==='bar'||kind==='rail'?selected.height*(.45+i*.22):0,height:Math.max(.45,selected.height*.65),width:1,color:style.color,material:style.material}));if(name==='water')selected.type='Liverpool';updateUI();draw();status('Estilo aplicado')}
function phase4Controls(){let inspector=$('#inspector');if(!inspector||$('#phase4Controls'))return;let box=document.createElement('div');box.id='phase4Controls';box.className='card';box.innerHTML='<strong>Estilos profesionales</strong><div class="row" style="margin-top:8px"><button class="btn" data-style="classic">Clásico</button><button class="btn" data-style="sponsor">Patrocinador</button></div><div class="row" style="margin-top:8px"><button class="btn" data-style="natural">Natural</button><button class="btn" data-style="water">Agua</button></div>';box.querySelectorAll('[data-style]').forEach(b=>b.onclick=()=>applyObstacleStyle(b.dataset.style));inspector.appendChild(box)}
function applyScenePreset(kind){history();let sets={training:[['Seto',8,8,4,2,1.2,'#3d8b4f'],['Árbol',72,8,3,3,7,'#2f7d32'],['Árbol',72,52,3,3,7,'#2f7d32']],competition:[['Tribuna',40,4,24,5,4,'#53657a'],['Cartelería',8,30,2,8,2,'#e1b12c'],['Cartelería',72,30,2,8,2,'#e1b12c']],indoor:[['Gradas indoor',40,4,30,5,5,'#667787'],['Muro lateral',4,30,2,60,5,'#7d8992'],['Muro lateral',76,30,2,60,5,'#7d8992']]}[kind]||[];sceneObjects=sets.map(([name,x,y,width,depth,height,color])=>({id:uid(),name,category:'Escenario',description:kind,material:'Escenografía',color,x,y,scale:1,rotation:0,dimensions:{width,depth,height}}));selectedScene=null;updateUI();draw();status('Escenario aplicado')}
function phase5Controls(){let panel=$('#rightPanel');if(!panel||$('#phase5Controls'))return;let box=document.createElement('div');box.id='phase5Controls';box.className='card';box.innerHTML='<strong>Escenarios rápidos</strong><div class="row" style="margin-top:8px"><button class="btn" data-scene="training">Entrenamiento</button><button class="btn" data-scene="competition">Concurso</button></div><button class="btn" data-scene="indoor" style="width:100%;margin-top:8px">Pista cubierta</button>';box.querySelectorAll('[data-scene]').forEach(b=>b.onclick=()=>applyScenePreset(b.dataset.scene));panel.appendChild(box)}
