// Integración de producción visual: proyecto limpio, paneles independientes,
// orden de escena, inspección ampliada y adaptación al área de trabajo.
let hoverObstacle=null,hoverSceneObject=null;
function resetProject(){history();W=80;H=60;objects=[];assets=[];sceneRefs=[];sceneObjects=[];route=[];selected=null;selectedScene=null;routeSelection=null;routeDrag=null;placeType=null;draft=null;routeMode=false;connectMode=false;geometryConnectMode=false;placingCoursePoint=false;placingLinePoint=false;anim=false;executionRunning=false;$('#arenaW').value=W;$('#arenaH').value=H;$('#routeMode').classList.remove('active');$('#connectMode').classList.remove('active');$('#addCoursePoint').classList.remove('active');$('#addCoursePoint').textContent='Punto al recorrido';$('#addLinePointMode').classList.remove('active');$('#addLinePointMode').textContent='Punto a la línea';setMode('seleccionar');updateUI();draw();status('Nuevo proyecto creado: área de trabajo limpia')}
$('#newProject').onclick=resetProject;
function togglePanel(side,force){let cls=side==='left'?'panel-hidden-left':'panel-hidden-right',on=force===undefined?!document.body.classList.contains(cls):force;document.body.classList.toggle(cls,on);let b=$(side==='left'?'#leftCollapse':'#rightCollapse');if(b)b.textContent=side==='left'?(on?'▶':'◀'):(on?'◀':'▶');setTimeout(resize,80)}
$('#leftCollapse').onclick=()=>togglePanel('left');$('#rightCollapse').onclick=()=>togglePanel('right');$('#leftToggle').onclick=()=>togglePanel('left');$('#rightToggle').onclick=()=>togglePanel('right');
function sceneNode(o){return route.find(n=>n.kind==='sceneObject'&&n.objectId===o.id)}
function sceneNodePoint(n){let o=sceneObjects.find(x=>x.id===n.objectId);return o?{x:o.x,y:o.y}:{x:n.x||0,y:n.y||0}}
const priorNodePoints=nodePoints;nodePoints=function(n){if(n?.kind==='sceneObject')return[sceneNodePoint(n)];return priorNodePoints(n)};
const priorIsCourseNode=isCourseNode;isCourseNode=function(n){return priorIsCourseNode(n)||n.kind==='sceneObject'||n.kind==='courseControl'};
const priorRouteLabel=routeLabel;routeLabel=function(n){if(n.kind==='sceneObject'){let o=sceneObjects.find(x=>x.id===n.objectId);return 'Objeto · '+(o?.name||'escena')}if(n.kind==='courseControl')return 'Punto verde';return priorRouteLabel(n)};
function addSceneToRoute(o){if(!o||sceneNode(o))return;history();route.push({id:uid(),kind:'sceneObject',objectId:o.id,x:o.x,y:o.y});routeSelection=route.at(-1);selected=null;updateUI();draw();status('Objeto incorporado al orden del recorrido')}
function drawHoverInspection(){let o=hoverObstacle,s=hoverSceneObject;if(!o&&!s){hideHoverInspection();return}let label=o?`${o.num||'?'} · ${o.type}`:(s.name||'Objeto');let details=o?`Ancho ${o.width.toFixed(1)} m · Altura ${o.height.toFixed(1)} m · ${Math.round(o.rot)}°`:`${s.category||'Objeto'} · escala ${(s.scale||1).toFixed(2)}×`;let box=$('#hoverInspection');if(!box){box=document.createElement('div');box.id='hoverInspection';box.className='hover-inspection';$('#stage').appendChild(box)}box.innerHTML=`<strong>${label}</strong><span>${details}</span><span>Toque para seleccionar y editar</span>`;box.style.display='block'}
