const priorDrawForHover=draw;draw=function(){priorDrawForHover();drawHoverInspection()};
canvas.addEventListener('pointermove',e=>{if(drag||sceneDrag||routeDrag||obstacleDrag)return;let q=pointerPos(e);hoverObstacle=hit(q.x,q.y);hoverSceneObject=hoverObstacle?null:hitSceneObject(q.x,q.y);if(hoverObstacle||hoverSceneObject)draw();else hideHoverInspection()});
