let cinematicRunning=false,cinematicElapsed=0,cinematicShotIndex=0,cinematicLast=0,cinematicRaf=0;
const cinematicShots=[
 {id:'opening',name:'Apertura aérea',duration:4,from:{view:'3d',yaw:-55,pitch:68,zoom:8},to:{view:'3d',yaw:-38,pitch:58,zoom:11}},
 {id:'drone',name:'Seguimiento drone',duration:7,from:{view:'3d',yaw:-38,pitch:58,zoom:11},to:{view:'3d',yaw:-18,pitch:48,zoom:13}},
 {id:'rider',name:'Vista del jinete',duration:6,from:{view:'3d',yaw:-12,pitch:28,zoom:14},to:{view:'3d',yaw:10,pitch:32,zoom:15}},
 {id:'jump',name:'Salto destacado',duration:5,from:{view:'3d',yaw:-25,pitch:38,zoom:15},to:{view:'3d',yaw:25,pitch:42,zoom:16}},
 {id:'closing',name:'Cierre cinematográfico',duration:4,from:{view:'3d',yaw:25,pitch:48,zoom:13},to:{view:'3d',yaw:55,pitch:62,zoom:9}}
];
function lerp(a,b,t){return a+(b-a)*t}function applyCinematicCamera(shot,t){let f=shot.from,to=shot.to;view=to.view;yaw=lerp(f.yaw,to.yaw,t)*Math.PI/180;pitch=lerp(f.pitch,to.pitch,t)*Math.PI/180;zoom=lerp(f.zoom,to.zoom,t);$('#yaw').value=(yaw*180/Math.PI).toFixed(0);$('#pitch').value=(pitch*180/Math.PI).toFixed(0);$('#zoom').value=zoom;$('#camPill').textContent='Plano: '+shot.name}
function cinematicFrame(now){if(!cinematicRunning)return;let dt=cinematicLast?(now-cinematicLast)/1000:0;cinematicLast=now;let shot=cinematicShots[cinematicShotIndex];cinematicElapsed+=dt;if(cinematicElapsed>=shot.duration){cinematicElapsed=0;cinematicShotIndex++;if(cinematicShotIndex>=cinematicShots.length){cinematicRunning=false;cinematicShotIndex=0;$('#cinemaPlay').textContent='▶ Reproducir secuencia';status('Secuencia cinematográfica terminada');draw();return}shot=cinematicShots[cinematicShotIndex]}applyCinematicCamera(shot,Math.min(1,cinematicElapsed/shot.duration));showHorseRider=true;draw();cinematicRaf=requestAnimationFrame(cinematicFrame)}
