async function recordCinematic(){if(cinematicRecording||cinematicRunning){status('La secuencia ya está en marcha');return}if(!canvas.captureStream||typeof MediaRecorder==='undefined'){status('Este Safari no permite grabar la presentación');return}let stream=canvas.captureStream(30),mime=['video/mp4;codecs=avc1.42E01E','video/mp4','video/webm;codecs=vp9','video/webm'].find(t=>MediaRecorder.isTypeSupported?.(t))||'',recorder;try{recorder=new MediaRecorder(stream,mime?{mimeType:mime}:undefined)}catch{status('No se pudo iniciar la grabación');return}let chunks=[];cinematicRecording=true;let b=$('#recordCinematic');b.disabled=true;b.textContent='Grabando presentación…';recorder.ondataavailable=e=>{if(e.data?.size)chunks.push(e.data)};recorder.onstop=async()=>{let type=recorder.mimeType||mime||'video/webm',ext=type.includes('mp4')?'mp4':'webm';stream.getTracks().forEach(t=>t.stop());cinematicRecording=false;b.disabled=false;b.textContent='Grabar presentación cinematográfica';let blob=new Blob(chunks,{type});if(await deliverExport(blob,`faas_cinematic_presentation_${new Date().toISOString().slice(0,10)}.${ext}`,type))status('Presentación cinematográfica guardada')};recorder.start();startCinematic();let watch=setInterval(()=>{if(!cinematicRunning){clearInterval(watch);recorder.stop()}},100)}
