function advancedValidationNodes(){let start=route.find(n=>n.kind==='point'&&n.marker==='start'),finish=route.find(n=>n.kind==='point'&&n.marker==='finish'),nodes=[];if(start)nodes.push({label:'Salida',x:start.x,y:start.y,kind:'start'});courseOrderedObjects().forEach((o,i)=>nodes.push({label:`${o.num||i+1} · ${o.type}`,x:o.x,y:o.y,kind:'obstacle',direction:Math.round(o.rot||0),object:o}));if(finish)nodes.push({label:'Llegada',x:finish.x,y:finish.y,kind:'finish'});return nodes}
function buildAdvancedValidation(){let stride=Math.max(2,+$('#strideLength')?.value||3.5),min=Math.max(.1,+$('#validationMinDistance')?.value||4),max=Math.max(min,+$('#validationMaxDistance')?.value||70),nodes=advancedValidationNodes(),segments=[];for(let i=1;i<nodes.length;i++){let a=nodes[i-1],b=nodes[i],meters=Math.hypot(b.x-a.x,b.y-a.y);segments.push({from:a.label,to:b.label,meters,strides:meters/stride,direction:b.direction??null,combination:a.kind==='obstacle'&&b.kind==='obstacle'&&meters<12,review:meters<min||meters>max})}let missing=objects.filter(o=>!obstacleNode(o)),warnings=[];if(!nodes.some(n=>n.kind==='start'))warnings.push('Falta definir la Salida.');if(!nodes.some(n=>n.kind==='finish'))warnings.push('Falta definir la Llegada.');if(!courseOrderedObjects().length)warnings.push('No hay obstáculos incorporados al orden del recorrido.');if(missing.length)warnings.push(`${missing.length} obstáculo(s) están en la pista pero fuera de Definir orden.`);segments.forEach(s=>{if(s.review)warnings.push(`Revisar ${s.from} → ${s.to}: ${s.meters.toFixed(1)} m.`);if(s.combination)warnings.push(`Posible combinación a revisar: ${s.from} → ${s.to} (${s.meters.toFixed(1)} m).`)});let total=segments.reduce((a,s)=>a+s.meters,0);return{timestamp:new Date().toISOString(),arena:{width:W,length:H},settings:{stride,minDistance:min,maxDistance:max},complete:warnings.length===0,totalMeters:total,totalStrides:total/stride,nodes,segments,missingObstacles:missing.map(o=>({id:o.id,num:o.num||'',type:o.type,x:o.x,y:o.y, direction:Math.round(o.rot||0)})),warnings}}
function renderAdvancedValidation(){let box=$('#advancedValidationReport');if(!box)return;let d=lastAdvancedValidation||buildAdvancedValidation(),statusText=d.complete?'✓ Recorrido completo dentro de los parámetros de revisión.':'⚠ Se requiere revisión técnica.';box.innerHTML=`<p class="${d.complete?'good':'warning'}"><b>${statusText}</b></p><p class="tiny">Total: ${d.totalMeters.toFixed(1)} m · ${d.totalStrides.toFixed(1)} trancos · ${d.segments.length} tramo(s)</p>${d.segments.length?'<ul class="tiny">'+d.segments.map(s=>`<li>${s.from} → ${s.to}: ${s.meters.toFixed(1)} m · ${s.strides.toFixed(1)} trancos${s.direction!==null?' · dirección '+s.direction+'°':''}${s.combination?' · combinación a revisar':''}${s.review?' · fuera del rango elegido':''}</li>`).join('')+'</ul>':''}${d.warnings.length?'<p class="tiny warning">'+d.warnings.join('<br>')+'</p>':'<p class="tiny good">No se detectaron pendientes con los parámetros actuales.</p>'}`}
