/* FAAS CLEAN INTERFACE · preserve legacy modules without visual clutter */
function applyCleanInterface(){
  const hiddenIds=[
    'phase4Controls','phase5Controls','phase6Controls','phase7Controls',
    'phase8Controls','phase9Controls','phase10Controls','phase11Controls',
    'phase12Controls','phase13Controls','phase14Controls','phase15Controls',
    'phase16Controls','phase17Controls','phase18Controls','phase19Controls',
    'phase20to23Controls'
  ];
  hiddenIds.forEach(id=>{const el=document.getElementById(id);if(el)el.style.display='none'});
  const construction=[...document.querySelectorAll('#inspector .card')]
    .find(el=>el.querySelector('strong')?.textContent.includes('Construcción del obstáculo'));
  if(construction)construction.style.display='none';
  document.querySelectorAll('.jump[data-type]').forEach(btn=>{
    const type=btn.dataset.type;
    if(type==='Oxer'){
      const label=btn.querySelector('span');
      if(label)label.textContent='Paralela';
      btn.title='Paralela';
      btn.style.display='';
    }else if(type!=='Vertical'){
      btn.style.display='none';
    }
  });
  const panel=document.getElementById('rightPanel');
  if(panel&&!document.getElementById('cleanModeCard')){
    const card=document.createElement('div');
    card.id='cleanModeCard';
    card.className='card';
    card.innerHTML='<strong>FAAS · modo limpio</strong><p class="tiny">Recorrido, trazado, obstáculos, ejecución y guardado.</p>';
    panel.insertBefore(card,panel.firstChild);
  }
  const premium=document.getElementById('premiumControls');
  if(premium){
    const title=premium.querySelector('strong');
    if(title)title.textContent='Obstáculos premium';
    const note=premium.querySelector('p.tiny:last-child');
    if(note)note.textContent='Vertical Premium disponible. Paralela: modelo de referencia pendiente de incorporar.';
  }
}
const cleanBaseUI=updateUI;
updateUI=function(){cleanBaseUI();applyCleanInterface()};
applyCleanInterface();


/* FAAS CORE UI RESTORE · mobile and tablet controls */
function restoreCoreInterface(){
  const left=document.getElementById('leftPanel');
  const right=document.getElementById('rightPanel');
  document.body.classList.remove('panel-hidden-left','panel-hidden-right');
  if(left)left.classList.add('show');
  if(right&&window.innerWidth>900)right.classList.add('show');
}
function setCorePanel(side,visible){
  const id=side==='left'?'leftPanel':'rightPanel';
  const el=document.getElementById(id);
  if(window.innerWidth<=900){
    if(el)el.classList.toggle('show',visible);
  }else{
    document.body.classList.toggle(side==='left'?'panel-hidden-left':'panel-hidden-right',!visible);
  }
  resize();
}
document.getElementById('leftToggle')?.addEventListener('click',()=>setCorePanel('left',!document.getElementById('leftPanel')?.classList.contains('show')));
document.getElementById('rightToggle')?.addEventListener('click',()=>setCorePanel('right',!document.getElementById('rightPanel')?.classList.contains('show')));
document.getElementById('leftCollapse')?.addEventListener('click',()=>setCorePanel('left',false));
document.getElementById('rightCollapse')?.addEventListener('click',()=>setCorePanel('right',false));
restoreCoreInterface();


const FAAS_HORSE_IMAGE="data:image/png;base64,";

/* Caballo cenital — distancia real sobre la misma polilínea que el trazo. */
const horseDefaults={enabled:true,length:3.5,rotation:-90,gap:0,duration:40,brightness:100,contrast:100,saturation:100,opacity:100,src:FAAS_HORSE_IMAGE};
let horseSettings={...horseDefaults},horseImage=new Image(),horseReady=false,horseAppearance=null,horseAppearanceKey="";
let zenPaths=[],zenTotal=0,zenDistance=0,zenActive=false,zenPaused=false,zenRaf=0,zenLast=null,zenSignature='';
const zenClamp=(x,a,b)=>Math.max(a,Math.min(b,x));
function normalizeHorse(raw={}){
 const s={...horseDefaults};
 for(const [k,a,b] of [['length',.5,12],['rotation',-360,360],['gap',0,5],['duration',5,300],['brightness',20,180],['contrast',20,180],['saturation',0,200],['opacity',10,100]]){
  const n=Number(raw[k]);if(raw[k]!==undefined&&Number.isFinite(n))s[k]=zenClamp(n,a,b);
 }
 s.enabled=raw.enabled!==false;
 if(typeof raw.src==='string'&&/^data:image\/(png|jpeg|webp);base64,/.test(raw.src)&&raw.src.length<4000000)s.src=raw.src;
 return s;
}
function loadHorseImage(){
 horseReady=false;const img=new Image();
 img.onload=()=>{if(img!==horseImage)return;horseReady=true;draw()};
 img.onerror=()=>status('No se pudo cargar la imagen del caballo. Prueba con PNG o JPG.');
 horseImage=img;img.src=horseSettings.src;
}
function zenMakePath(points){
 const p=[];for(const v of points){if(!Number.isFinite(v?.x)||!Number.isFinite(v?.y))continue;if(!p.length||Math.hypot(v.x-p.at(-1).x,v.y-p.at(-1).y)>1e-8)p.push({x:v.x,y:v.y})}
 const distances=[0];for(let i=1;i<p.length;i++)distances.push(distances.at(-1)+Math.hypot(p[i].x-p[i-1].x,p[i].y-p[i-1].y));
 return {points:p,distances,length:distances.at(-1)||0};
}
function zenSample(path,d){
 d=zenClamp(d,0,path.length);let lo=1,hi=path.points.length-1;
 while(lo<hi){let m=(lo+hi)>>1;if(path.distances[m]<d)lo=m+1;else hi=m}
 let a=path.points[lo-1],b=path.points[lo],t=(d-path.distances[lo-1])/(path.distances[lo]-path.distances[lo-1]);
 return{x:a.x+(b.x-a.x)*t,y:a.y+(b.y-a.y)*t,index:lo};
}
function zenBuild(){
 const courseIds=new Set(courseBaseNodes().map(n=>n.id));let used=false,items=[];
 for(const n of route){
  if(courseIds.has(n.id)||n.kind==='courseControl'){
   if(!used){const pts=allRoutePoints();if(pts.length>1)items.push(catmull(pts,18));used=true}
  }else if(['line','curve','connection','circle'].includes(n.kind))items.push(['line','circle'].includes(n.kind)?nodePoints(n):catmull(nodePoints(n),18));
 }
 zenPaths=items.map(zenMakePath).filter(p=>p.length>1e-6);zenTotal=0;
 for(const p of zenPaths){p.start=zenTotal;zenTotal+=p.length}
 zenSignature=JSON.stringify({route,objects:objects.map(o=>[o.id,o.x,o.y])});
}
function zenCurrent(){
 if(!zenPaths.length)return null;
 const p=zenPaths.find(p=>zenDistance<p.start+p.length-1e-8)||zenPaths.at(-1);
 return{path:p,d:zenClamp(zenDistance-p.start,0,p.length)};
}
function zenReset(){cancelAnimationFrame(zenRaf);zenRaf=0;zenLast=null;zenDistance=0;zenActive=false;zenPaused=false;executionRunning=false;executionProgress=0;$('#play').textContent='▶ Ejecutar';draw()}
function zenFrame(now){
 zenRaf=0;if(!executionRunning)return;
 if(zenLast!==null)zenDistance=Math.min(zenTotal,zenDistance+(now-zenLast)/1000*zenTotal/horseSettings.duration);
 zenLast=now;executionProgress=zenTotal?zenDistance/zenTotal:0;
 if(zenDistance>=zenTotal){executionRunning=false;zenPaused=false;$('#play').textContent='▶ Repetir';status('Recorrido terminado · '+horseSettings.duration+' segundos')}
 draw();if(executionRunning)zenRaf=requestAnimationFrame(zenFrame);
}
// Desactiva el reloj antiguo: solo hay un reloj para caballo y trazo.
tick=function(){};
startExecution=function(){
 if(horseSettings.enabled&&!horseReady){status('Espera a que cargue la imagen del caballo');return}
 cancelAnimationFrame(zenRaf);zenBuild();
 if(!zenTotal){status('Dibuja una línea o carga un recorrido antes de ejecutar');return}
 if(cinematicRunning)stopCinematic();
 view='top';$('#camPill').textContent='Cámara: Cenital';selected=null;selectedScene=null;routeSelection=null;
 zenDistance=0;zenLast=null;zenActive=true;zenPaused=false;executionRunning=true;executionProgress=0;anim=false;
 $('#play').textContent='⏸ Pausar';if(innerWidth<=900){$('#leftPanel').classList.remove('show');$('#rightPanel').classList.remove('show');resize()}status('Recorrido cenital · '+horseSettings.duration+' segundos');draw();zenRaf=requestAnimationFrame(zenFrame);
};
$('#play').onclick=()=>{
 if(recordingExecution){status('Grabación en curso; espera al final del recorrido');return}
 if(executionRunning){executionRunning=false;zenPaused=true;cancelAnimationFrame(zenRaf);zenLast=null;$('#play').textContent='▶ Continuar';draw();return}
 if(zenPaused){executionRunning=true;zenPaused=false;zenLast=null;$('#play').textContent='⏸ Pausar';zenRaf=requestAnimationFrame(zenFrame)}else startExecution();
};
const zenOldGeometry=drawRouteGeometry,zenOldRoute=drawRoute;
drawRouteGeometry=function(){if(!zenActive)zenOldGeometry()};
drawRoute=function(){if(!zenActive)zenOldRoute()};
drawExecutionOverlay=function(){};
drawHorseRider=function(){};
function zenStroke(path,d,guide=false){
 if(d<=0)return;const end=zenSample(path,d);ctx.beginPath();
 path.points.slice(0,end.index).forEach((p,i)=>{const q=project(p.x,p.y,0);i?ctx.lineTo(q.x,q.y):ctx.moveTo(q.x,q.y)});
 const q=project(end.x,end.y,0);ctx.lineTo(q.x,q.y);
 ctx.strokeStyle=guide?'rgba(255,255,255,.25)':executionColor;ctx.lineWidth=guide?1:executionWidth;
 ctx.setLineDash(guide?[]:executionDash==='dashed'?[12,9]:executionDash==='dotted'?[2,8]:[]);ctx.lineCap='round';ctx.lineJoin='round';ctx.stroke();
}
function zenHorseTexture(){
 const key=[horseSettings.src,horseSettings.brightness,horseSettings.contrast,horseSettings.saturation].join('|');
 if(horseAppearanceKey===key&&horseAppearance)return horseAppearance;
 const c=document.createElement('canvas');c.width=horseImage.width;c.height=horseImage.height;
 const cx=c.getContext('2d');cx.drawImage(horseImage,0,0);const image=cx.getImageData(0,0,c.width,c.height),d=image.data;
 const b=horseSettings.brightness/100,k=horseSettings.contrast/100,s=horseSettings.saturation/100;
 for(let i=0;i<d.length;i+=4){const r=d[i]*b,g=d[i+1]*b,bl=d[i+2]*b,l=.2126*r+.7152*g+.0722*bl;
 d[i]=(l+(r-l)*s-127.5)*k+127.5;d[i+1]=(l+(g-l)*s-127.5)*k+127.5;d[i+2]=(l+(bl-l)*s-127.5)*k+127.5;}
 cx.putImageData(image,0,0);horseAppearance=c;horseAppearanceKey=key;return c;
}
function zenDraw(){
 const cur=zenCurrent();if(!cur)return;
 ctx.save();
 if(zenActive){for(const p of zenPaths){zenStroke(p,p.length,true);const d=zenClamp(zenDistance-p.start,0,p.length);const lag=horseSettings.enabled?horseSettings.length*.4+horseSettings.gap:0;zenStroke(p,p===cur.path?Math.max(0,d-lag):d)}}
 ctx.restore();
 if(!horseSettings.enabled||!horseReady||view!=='top')return;
 const p=zenSample(cur.path,cur.d),look=Math.max(.15,horseSettings.length*.15),a=zenSample(cur.path,cur.d-look),b=zenSample(cur.path,cur.d+look);
 const q=project(p.x,p.y,0),angle=Math.atan2(b.y-a.y,b.x-a.x)+horseSettings.rotation*Math.PI/180;
 const h=horseSettings.length*q.s,w=h*horseImage.width/horseImage.height;
 ctx.save();ctx.translate(q.x,q.y);ctx.rotate(angle);ctx.globalAlpha=horseSettings.opacity/100;
 ctx.drawImage(zenHorseTexture(),-w/2,-h/2,w,h);ctx.restore();
}
// Un solo render completo: fondo, herramientas, línea y caballo en el mismo fotograma.
let zenRenderQueued=false;
draw=function(){if(zenRenderQueued)return;zenRenderQueued=true;requestAnimationFrame(()=>{
 zenRenderQueued=false;
 const sig=JSON.stringify({route,objects:objects.map(o=>[o.id,o.x,o.y])});
 if(sig!==zenSignature){if(zenActive)zenReset();zenBuild()}
 const gridBefore=showGrid;if(zenActive)showGrid=false;
 renderNow();showGrid=gridBefore;zenDraw();
 const out=$('#horseProgress');if(out)out.textContent=zenActive?`${(executionProgress*horseSettings.duration).toFixed(1)} / ${horseSettings.duration} s`:'Listo para ejecutar';
})};
